"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[73784],{3331:(e,r,t)=>{t.d(r,{R:()=>o,x:()=>a});var n=t(36672);const i={},s=n.createContext(i);function o(e){const r=n.useContext(s);return n.useMemo((function(){return"function"==typeof e?e(r):{...r,...e}}),[r,e])}function a(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),n.createElement(s.Provider,{value:r},e.children)}},52351:(e,r,t)=>{t.r(r),t.d(r,{assets:()=>l,contentTitle:()=>a,default:()=>g,frontMatter:()=>o,metadata:()=>n,toc:()=>d});const n=JSON.parse('{"id":"2023/04/17","title":"2023-04-17","description":"De-Stressing Booking.com","source":"@site/i18n/nb/docusaurus-plugin-content-docs/current/2023/04/17.md","sourceDirName":"2023/04","slug":"/2023/04/17","permalink":"/nb/2023/04/17","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/nb/docusaurus-plugin-content-docs//current/2023/04/17.md","tags":[],"version":"current","frontMatter":{"localized_date":"17. april 2023","top_news":"De-Stressing Booking.com"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-18","permalink":"/nb/2023/04/18"},"next":{"title":"2023-04-16","permalink":"/nb/2023/04/16"}}');var i=t(23420),s=t(3331);const o={localized_date:"17. april 2023",top_news:"De-Stressing Booking.com"},a="2023-04-17",l={},d=[{value:"De-Stressing Booking.com",id:"de-stressing-bookingcom",level:2},{value:"Jeg brukte Stable Diffusion og Dreambooth til \xe5 lage et kunstportrett av hunden min.",id:"jeg-brukte-stable-diffusion-og-dreambooth-til-\xe5-lage-et-kunstportrett-av-hunden-min",level:2},{value:"AT&amp;T Wireless Traffic Shaping gj\xf8r tilsynelatende noen nettsteder ubrukelige.",id:"att-wireless-traffic-shaping-gj\xf8r-tilsynelatende-noen-nettsteder-ubrukelige",level:2},{value:"Future Blues - Emily&#39;s Cowboy Bebop Page (1999)",id:"future-blues---emilys-cowboy-bebop-page-1999",level:2},{value:"Oppvaskmaskin Laks",id:"oppvaskmaskin-laks",level:2},{value:"Pico3D: Open World 3D Game Engine for PicoSystem (RP2040 Microcontroller).",id:"pico3d-open-world-3d-game-engine-for-picosystem-rp2040-microcontroller",level:2},{value:"Wayback: Selvhostet arkiveringstjeneste integrert med Internett-arkivet",id:"wayback-selvhostet-arkiveringstjeneste-integrert-med-internett-arkivet",level:2},{value:"Det raskeste matematiske satsbiblioteket for nettet.",id:"det-raskeste-matematiske-satsbiblioteket-for-nettet",level:2},{value:"&#39;Algebra for ingen&#39; mislykkes i San Francisco.",id:"algebra-for-ingen-mislykkes-i-san-francisco",level:2},{value:"FSF smeller Google over \xe5 slippe JPEG-XL i Chrome",id:"fsf-smeller-google-over-\xe5-slippe-jpeg-xl-i-chrome",level:2}];function k(e){const r={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(r.header,{children:(0,i.jsx)(r.h1,{id:"2023-04-17",children:"2023-04-17"})}),"\n",(0,i.jsx)(r.h2,{id:"de-stressing-bookingcom",children:"De-Stressing Booking.com"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.alexcharlton.co/projects/booking-com-de-stresser",children:"Original"}),'.\nSkribenten deler en meningsytring om overforbruk av overtalelsestaktikker p\xe5 e-handelsnettsteder, spesielt Booking.com, og introduserer Chrome-utvidelsen deres, "De-stresser", som fjerner stressfremkallende meldinger og varsler fra Booking.com, og gir brukerne en mer behagelig opplevelse. Ved \xe5 skjule overtalelseskoder og tilpasse spr\xe5ket slik at det h\xf8res mer positivt ut, gir De-stresser brukerne en roligere og mer avslappet bestillingsopplevelse. Utvidelsen er n\xe5 live og tilgjengelig for bruk p\xe5 Booking.com.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35590734",children:"Discussion Service"}),'.\nBooking.com m\xf8ter kritikk for sin bruk av salgstaktikker med h\xf8yt trykk, inkludert hastemeldinger og popup-vinduer som kan avskrekke brukerne. Kritikere hevder at denne tiln\xe6rmingen prioriterer kortsiktige beregninger fremfor langsiktig kundelojalitet. Brukere rapporterer at de har funnet m\xe5ter \xe5 omg\xe5 disse taktikkene p\xe5, blant annet ved \xe5 bruke utvidelser for \xe5 blokkere eller filtrere dem. I mellomtiden diskuterer Discussion Service-brukere fordelene med A/B-testing, og noen peker p\xe5 potensialet for \xe5 skape "m\xf8rke m\xf8nstre" p\xe5 nettsteder. Til tross for disse bekymringene fortsetter mange brukere \xe5 bruke bestillingsaggregatorer som Booking.com og Expedia, enten for enkelhets skyld eller fordi de tilbyr gunstige priser og avbestillingsregler. Noen eksperter advarer om at bestilling direkte hos hotellene kan gi bedre tvistel\xf8sningsmuligheter, mens andre p\xe5peker at provisjonssatsene for bestillingsnettsteder kan variere mye avhengig av hotellet. Ikke desto mindre kan lojalitetsprogrammer fra hoteller gi betydelige fordeler for hyppige reisende.']}),"\n",(0,i.jsx)(r.h2,{id:"jeg-brukte-stable-diffusion-og-dreambooth-til-\xe5-lage-et-kunstportrett-av-hunden-min",children:"Jeg brukte Stable Diffusion og Dreambooth til \xe5 lage et kunstportrett av hunden min."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.shruggingface.com/blog/how-i-used-stable-diffusion-and-dreambooth-to-create-a-painted-portrait-of-my-dog",children:"Original"}),".\nArtikkelen diskuterer bruk av Stable Diffusion og Dreambooth AI-teknikker for \xe5 lage et malt portrett av en hund av h\xf8y kvalitet. Forfatteren deler hele arbeidsflyten og gir detaljerte instruksjoner om hvordan man trener en Dreambooth-modell p\xe5 bilder av hunden sin. Artikkelen diskuterer ogs\xe5 bruken av oppskalering for \xe5 forst\xf8rre sm\xe5 bilder for utskrifter av h\xf8y kvalitet og introduserer Stable Diffusion som en game-changer for tekst-til-bilde-generativ kunst."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35592847",children:"Discussion Service"}),".\nEn Discussion Service-bruker brukte Stable Diffusion og Dreambooth til \xe5 lage et kunstportrett av hunden sin, mens kommentarene diskuterte motstanden mot AI-kunst og debatter om opphavsrett og rettferdig bruk. Bruken av generativ kunstig intelligens til kunst reiser etiske sp\xf8rsm\xe5l om opphavsrett og rimelig bruk, og det er delte meninger om saken. Noen kritiserte Stable Diffusion for \xe5 bruke ukompenserte stj\xe5lne kunstverk som treningsdata, mens andre roste teknologien og dens potensial for videre innovasjon p\xe5 omr\xe5det."]}),"\n",(0,i.jsx)(r.h2,{id:"att-wireless-traffic-shaping-gj\xf8r-tilsynelatende-noen-nettsteder-ubrukelige",children:"AT&T Wireless Traffic Shaping gj\xf8r tilsynelatende noen nettsteder ubrukelige."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://adriano.fyi/post/2023/2023-04-16-att-traffic-shaping-makes-websites-unusable/",children:"Original"}),'.\nAT&Ts "ubegrensede" 100 Mbit-plan med 50 GB for prioriterte data kan aggressivt trafikkform, noe som f\xf8rer til at noen nettsteder blir ubrukelige, mens en test viste at et Verizon SIM-kort ikke hadde det samme problemet. Akamai-trafikk viser tegn p\xe5 bevisst manipulering av TCP-str\xf8mmen. Trafikkforming p\xe5virker bare rene datakontoer p\xe5 bedriftskontoer.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35592607",children:"Discussion Service"}),".\nAT&T Wireless struper angivelig IP-adresser for noen videostr\xf8mmingsnettsteder, noe som gj\xf8r noen nettsteder ubrukelige og for\xe5rsaker avvik i Internett-hastighetstester. Brukere har foresl\xe5tt l\xf8sninger som \xe5 sende inn en klage til FCC, bruke et VPN for \xe5 omg\xe5 struping eller pr\xf8ve et annet APN. Noen kommentatorer er skeptiske til om det ligger skumle hensikter bak strupingen, mens andre foresl\xe5r l\xf8sninger som hastighetsgrenser eller nedgradering av videokvaliteten for \xe5 bevare datatildelingen."]}),"\n",(0,i.jsx)(r.h2,{id:"future-blues---emilys-cowboy-bebop-page-1999",children:"Future Blues - Emily's Cowboy Bebop Page (1999)"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://futureblues.com/",children:"Original"}),".\nBeklager, det er ingen tekst gitt for meg \xe5 oppsummere."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35589124",children:"Discussion Service"}),".\nDiscussion Service-brukere uttrykker nostalgi for den originale og kreative utformingen av klassiske nettsteder, i kontrast til den standardiserte, st\xf8yende og monetariserte naturen til moderne nettsteder, noe som tyder p\xe5 en lengsel etter mer kunstneriske, individualitetsfokuserte medielandskap. Diskusjonspunkter dukker opp n\xe5r man sammenligner Wikipedia og Fandom, og skillet mellom mobile og stasjon\xe6re nettsteder, og utformingen av nettstedet inspirerer til b\xe5de nostalgi og forbl\xf8ffelse over dets lange levetid. Alt i alt gir innlegget et innblikk i brukernes gode minner fra det tidlige internett og gir en plattform for \xe5 diskutere nettets n\xe5v\xe6rende tilstand."]}),"\n",(0,i.jsx)(r.h2,{id:"oppvaskmaskin-laks",children:"Oppvaskmaskin Laks"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://en.wikipedia.org/wiki/Dishwasher_salmon",children:"Original"}),".\nOppvaskmaskinlaks er en fiskerett som lages ved \xe5 pakke inn laksestykker i minst to lag aluminiumsfolie og plassere den i oppvaskmaskinen under vaske- og t\xf8rkesyklusen. Metoden ble f\xf8rst demonstrert i USA av Vincent Price i 1975 og har siden blitt omtalt i ulike medier. Det er imidlertid bekymringer knyttet til temperaturene i oppvaskmaskiner, noe som kan f\xf8re til ufullstendig tilberedning og potensielle helserisikoer."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35586683",children:"Discussion Service"}),".\nEn Hacker News-artikkel om tilberedning av laks i oppvaskmaskin utl\xf8ser en debatt om sikkerheten ved tilberedningsmetoden, der brukere i n\xe6ringsmiddelindustrien im\xf8teg\xe5r p\xe5standene i en YouTubers unders\xf8kelse. Selv om sikkerheten ved tilberedning i oppvaskmaskin avhenger av flere faktorer, kreves det minst 63 \xb0C i 15 sekunder for \xe5 drepe bakterier i laks."]}),"\n",(0,i.jsx)(r.h2,{id:"pico3d-open-world-3d-game-engine-for-picosystem-rp2040-microcontroller",children:"Pico3D: Open World 3D Game Engine for PicoSystem (RP2040 Microcontroller)."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://github.com/bernhardstrobl/Pico3D",children:"Original"}),".\nPico3D-spillmotoren bruker den andre kjernen i RP2040 som en dedikert rasterizer / GPU for \xe5 kj\xf8re et komplett \xe5pent 3D-spill p\xe5 en $ 1 mikrokontroller. Motoren inneholder en liten by og utkanten med zombier som kan skytes, med Blender-veiledninger tilgjengelig for \xe5 lage spillverdener. Motorsimuleringen inkluderer for \xf8yeblikket 50 NPC-er og 50 zombier samtidig, med gjengivelse optimalisert med avstand og visning av frustrasjon."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35589172",children:"Discussion Service"}),".\nEn ny 3D-spillmotor kalt Pico3D er utviklet for RP2040-mikrokontrolleren med en 120x120px-skjerm, og den mangler nok minne og video-RAM, men har et enhetlig API. Hackere er begeistret for kreative m\xe5ter \xe5 bruke Pico / RP2040 p\xe5, og den unike bruken av RAM-brikker i rammebufferen gj\xf8r at denne artikkelen skiller seg ut p\xe5 teknologisiden."]}),"\n",(0,i.jsx)(r.h2,{id:"wayback-selvhostet-arkiveringstjeneste-integrert-med-internett-arkivet",children:"Wayback: Selvhostet arkiveringstjeneste integrert med Internett-arkivet"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://github.com/wabarc/wayback",children:"Original"}),".\nWayback er et selvdrevet arkiveringsverkt\xf8y som tar sikte p\xe5 \xe5 ta \xf8yeblikksbilder av nettsider i tidskapsler. Det er gratis, \xe5pen kildekode, plattformuavhengig og muliggj\xf8r enklere integrering med ulike plattformer, inkludert Internet Archive, archive.today, IPFS og Telegraph. Det tilbyr ogs\xe5 flere installasjonsalternativer, blant annet via GitHub, Snapcraft, APT, RPM og Homebrew."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35586845",children:"Discussion Service"}),'.\nDen selvdrevne arkiveringstjenesten Wabarc tar \xf8yeblikksbilder av nettsider i "tidskapsler" og lagrer filer for offline bruk; Discussion Service-brukere kritiserer imidlertid den uklare README og mangelen p\xe5 dokumentasjon. Andre lignende prosjekter inkluderer ArchiveBox, Shiori, DiskerNet og SingleFile; HTTrack Website Copier anbefales for \xe5 laste ned et helt nettsted lokalt, mens Browsertrix/Brozzler gjennoms\xf8ker med hodel\xf8se nettlesere for n\xf8yaktighet. En Discussion Service-bruker anbefaler The Old Net for surfing i gamle/moderne nettlesere uten JS, og repo-linken trenger mer klarhet om delbarhet og etablerte arkiveringsstandarder.']}),"\n",(0,i.jsx)(r.h2,{id:"det-raskeste-matematiske-satsbiblioteket-for-nettet",children:"Det raskeste matematiske satsbiblioteket for nettet."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://katex.org/",children:"Original"}),".\nKaTeX er et raskt matematikksettingsbibliotek for nettet som tilbyr layout i utskriftskvalitet basert p\xe5 Donald Knuths TeX, har ingen avhengigheter og kan enkelt kombineres med nettstedsressurser for gjengivelse p\xe5 serversiden ved hjelp av Node.js. Det enkle API-et gjengir matematiske uttrykk effektivt, selv p\xe5 sider med flere uttrykk, uten nettleser- eller milj\xf8begrensninger, og det er \xe5pen kildekode under MIT-lisensen."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35588985",children:"Discussion Service"}),".\nKaTeX, det raskeste matematiske satsbiblioteket for nettet, mangler st\xf8tte for diagrammer, noe som gj\xf8r det uegnet for noen matematikere, mens MathJax og AsciiMath begge har lignende prosjekter. Et sammenligningsnettsted har blitt delt, og ytelsen og det praktiske ved \xe5 tilpasse markeringen til ulike sammenhenger debatteres av Hacker News-brukere."]}),"\n",(0,i.jsx)(r.h2,{id:"algebra-for-ingen-mislykkes-i-san-francisco",children:"'Algebra for ingen' mislykkes i San Francisco."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.joannejacobs.com/post/algebra-for-none-fails-in-san-francisco",children:"Original"}),'.\nSan Francisco Unified skoledistrikts "Algebra for none"-politikk klarte ikke \xe5 forbedre prestasjonene til svarte og latinamerikanske studenter i avansert matematikk, if\xf8lge en studie av Stanford-professorer, noe som resulterte i et \xf8kende prestasjonsgap. Beslutningen om \xe5 utsette algebra til niende klasse og plassere lavtpresterende og h\xf8ytpresterende elever i samme klasser hjalp ikke lavtpresterende elever og gjorde det vanskeligere for h\xf8ytpresterende elever \xe5 lykkes. Familier som har r\xe5d til det, har vendt seg til nettkurs eller privatskoler. En gruppe foreldre har anlagt s\xf8ksm\xe5l mot distriktet og hevder at det bryter med delstatsloven om rettferdig tilgang til avansert matematikk.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35595026",children:"Discussion Service"}),".\nSan Franciscos politikk med \xe5 utsette algebra til 9. klasse og plassere elever med lave, middels og h\xf8ye prestasjoner i de samme klassene har blitt kritisert, og noen foresl\xe5r at grunnleggende mattekonsepter b\xf8r undervises tidligere. Noen Discussion Service-brukere foresl\xe5r \xe5 stimulere akademisk og utenomfaglig suksess ved \xe5 knytte det til \xf8konomisk bel\xf8nning, mens andre hevder at subsidiering av h\xf8yere utdanning gjennom kredittsystemer for \xe5 betale for college senere ville v\xe6re en bedre l\xf8sning. Det er debatter om nytten av tradisjonell matematikkundervisning og effektiviteten av \xe5 \xf8ke finansieringen for \xe5 redusere klassest\xf8rrelsene, og noen brukere foresl\xe5r \xe5 undervise i matematikk gjennom tekniske problemer og fordelene med nettbasert undervisning."]}),"\n",(0,i.jsx)(r.h2,{id:"fsf-smeller-google-over-\xe5-slippe-jpeg-xl-i-chrome",children:"FSF smeller Google over \xe5 slippe JPEG-XL i Chrome"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.phoronix.com/news/FSF-Slams-Google-JPEG-XL",children:"Original"}),'.\nFree Software Foundation kritiserer Googles beslutning om \xe5 droppe JPEG-XL-st\xf8tte i Chrome, og fremhever behovet for valg av nettleser og frie medieformater. Til tross for oppr\xf8ret i samfunnet gikk Googles ingeni\xf8rer likevel videre med beslutningen, som fortsatt er en av de mest "stjernespekkede" sakene i Chromium-prosjektets historie. Brukerne har vist sterk st\xf8tte for JPEG-XL, men Googles fokus p\xe5 kontroll over frihet ser ut til \xe5 seire.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35589179",children:"Discussion Service"}),".\nGoogle m\xf8ter kritikk fra Free Software Foundation for \xe5 ha avviklet st\xf8tten for JPEG-XL i Chrome til tross for at det er tatt i bruk av store bildebehandlere. Noen brukere hevder at eldre formater som PNG og JPEG er tilstrekkelige, mens andre foretrekker kodeker som AVIF for video. Debatten dreier seg om levedyktigheten og innf\xf8ringen av nye bildeformater i \xf8kosystemet, med st\xf8tte og interesse fra bransjen for JPEG-XL, men innf\xf8ringen er avhengig av at alle de store nettleserne st\xf8tter det."]})]})}function g(e={}){const{wrapper:r}={...(0,s.R)(),...e.components};return r?(0,i.jsx)(r,{...e,children:(0,i.jsx)(k,{...e})}):k(e)}}}]);